#include "Phonemizer/JapaneseVCVPhonemizer.h"
#include "Phonemizer/AliasResolver.h"
#include "Singer/Singer.h"
namespace myvocal { QString JapaneseVCVPhonemizer::name()const{return QStringLiteral("Japanese VCV");} QString JapaneseVCVPhonemizer::vowelOf(const QString&l)const{static const QMap<QString,QString>v{{"あ","a"},{"い","i"},{"う","u"},{"え","e"},{"お","o"},{"か","a"},{"き","i"},{"く","u"},{"け","e"},{"こ","o"},{"さ","a"},{"し","i"},{"す","u"},{"せ","e"},{"そ","o"}};return v.value(l,l);} std::vector<Phoneme>JapaneseVCVPhonemizer::process(const std::vector<Note>&notes,const Singer&s){AliasResolver r(s);std::vector<Phoneme>out;QString prevVowel="a";for(size_t i=0;i<notes.size();++i){QString lyric=notes[i].getLyric().trimmed();QString alias=(i==0?lyric:prevVowel+QStringLiteral(" ")+lyric);auto e=r.resolve(alias);if(!e)e=r.resolve(lyric);if(!e)alias=lyric;Phoneme p{alias,static_cast<double>(notes[i].getStartTick()),static_cast<double>(notes[i].getDurationTick()),0,0,0,0,0,i};if(e){p.preutterance=e->preutterance;p.overlap=e->overlap;p.offset=e->offset;p.consonant=e->consonant;p.cutoff=e->cutoff;}out.push_back(std::move(p));prevVowel=vowelOf(lyric);}return out;} }
